def transform(grid):
    split = next(i for i, value in enumerate(grid[0]) if value == 5)
    width = split
    output = [[4] * width for _ in grid]
    for r, row in enumerate(grid):
        left = row[:width]
        right = row[split + 1:split + 1 + width]
        for c in range(width):
            if left[c] == 9 and right[c] == 4:
                output[r][c] = 3
    return output

